const incoming = $input.first();
const item = incoming.json || {};
const body = item.body && typeof item.body === 'object' && !Array.isArray(item.body) ? item.body : item;
const profile = body.profile && typeof body.profile === 'object' ? body.profile : {};
const question = String(body.question || body.notes || body.text || body.message || '').trim();
const explicitUrl = String(body.url || body.website_url || body.website || '').trim();
const urlMatch = question.match(/https?:\/\/[^\s)]+/i);
const url = explicitUrl || (urlMatch ? urlMatch[0] : '');
const sources = Array.isArray(body.sources) ? body.sources.slice(0, 8) : [];
const binary = { ...(incoming.binary || {}) };
for (let index = 0; index < sources.length; index++) {
  const file = sources[index] || {};
  const data = String(file.data || '').replace(/^data:[^,]*,/, '').replace(/\s/g, '');
  if (!data) continue;
  const name = String(file.name || `file-${index + 1}`);
  const mime = String(file.mime || 'application/octet-stream');
  const key = index === 0 && !binary.data ? 'data' : `data_${index}`;
  const buffer = Buffer.from(data, 'base64');
  if (!buffer.length) continue;
  try {
    binary[key] = await this.helpers.prepareBinaryData(buffer, name, mime);
  } catch (error) {
    binary[key] = { data, mimeType: mime, fileName: name };
  }
}
const notes = [
  question,
  profile.sellerName ? `Business: ${profile.sellerName}` : '',
  profile.offering ? `Offering: ${profile.offering}` : '',
  profile.icp ? `Ideal customer: ${profile.icp}` : '',
  profile.industry ? `Industry: ${profile.industry}` : '',
  profile.region ? `Region: ${profile.region}` : '',
  profile.maxLeads ? `Maximum leads: ${profile.maxLeads}` : '',
].filter(Boolean).join('\n');
return [{
  json: {
    input: body.input === 'sources' ? 'sources' : 'ask',
    notes,
    question,
    url,
    profile,
    attachment_count: Object.keys(binary).length,
  },
  binary,
}];

