const output = $("Structure Leads").first().json.output || {};
const icp = $("Generate ICP").first().json.output || {};
const rows = Array.isArray(output.leads) ? output.leads : [];
function blank(value) {
  const text = String(value ?? '').trim();
  if (!text || /^(not publicly found|unknown|n\/a|none|no public(?: email| contact)?)$/i.test(text)) return '';
  return text;
}
function hostOf(website) {
  try { return new URL(website).hostname.replace(/^www\./, ''); } catch (error) { return ''; }
}
const leads = rows.map((row) => {
  const website = String(row.website || row.website_url || row.url || '').trim();
  const domain = String(row.domain || '').trim().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0] || hostOf(website);
  const hook = blank(row.hook || row.personalized_icebreaker);
  const score = Number(row.icp_fit_score || 0);
  const priority = hook && (/^high$/i.test(String(row.priority || '')) || (!row.priority && score >= 7)) ? 'High' : 'Low';
  const emailText = blank(row.email);
  return {
    company: String(row.company || row.company_name || row.name || '').trim(),
    domain,
    website,
    hq: String(row.hq || row.hqAddress || row.headquarters || '').trim(),
    lat: row.lat == null || row.lat === '' || Number.isNaN(Number(row.lat)) ? null : Number(row.lat),
    lng: row.lng == null || row.lng === '' || Number.isNaN(Number(row.lng)) ? null : Number(row.lng),
    contact: blank(row.contact || row.contact_name),
    title: blank(row.title || row.contact_title),
    email: emailText.includes('@') ? emailText : '',
    pain: String(row.pain || row.fit_reasoning || '').trim(),
    hook,
    priority,
    source: String(row.source || website || '').trim(),
    photo: String(row.photo || row.logo || '').trim(),
  };
}).filter((row) => row.company);
const summary = String(icp.company_summary || '').replace(/\s+/g, ' ').trim();
const count = leads.length + (leads.length === 1 ? ' company.' : ' companies.');
const explanation = [summary, count].filter(Boolean).join(' ').slice(0, 600);
return [{ json: { ok: true, explanation, leads } }];
